export const SCENE_CATEGORIES=['glamour','portrait','cinematic','product','nature','atmosphere','action','custom'];
export const SCENE_MOTIONS=['subtle','natural','dynamic'];
export const SCENE_INTENTS={
 glamour:'An elegant adult fashion/glamour moment. Use only adults already established in the reference; restrained expression, posture or fabric movement. Preserve clothing and identity.',
 portrait:'A believable portrait moment, with a small natural change of expression or gaze if a person is visible. Preserve identity and appearance.',
 cinematic:'One coherent cinematic beat using the existing scene and its visible subjects. Give it a clear beginning, small development and settled ending.',
 product:'A restrained product presentation, preserving the exact shape, materials, markings and surrounding objects. Do not add hands or open hidden mechanisms.',
 nature:'A natural environmental moment: modest motion of visible weather, foliage or water, where present. Preserve landscape geometry.',
 atmosphere:'An atmospheric moment with subtle changes limited to elements present in the reference. Keep architecture and stationary objects stable.',
 action:'One readable, physically plausible action that the visible scene supports. Prefer one subject and one action; avoid a chain of stunts or rapid cuts.',
 custom:''
};
const sceneText=(v,max)=>{if(typeof v!=='string'||v.length>max)throw Error('Invalid scene text.');return v;};
export function defaultSceneSettings(){return {category:'cinematic',motion:'subtle',mood:'',direction:'',customCategory:'',source:'reference',language:'EN'};}
export function validateSceneSettings(raw){const defaults=defaultSceneSettings();if(!raw)return defaults;for(const [key,values]of [['category',SCENE_CATEGORIES],['motion',SCENE_MOTIONS],['source',['reference','result']],['language',['EN','HU','DE','FR','ES','IT','PT','PL']]])if(!values.includes(raw[key]))throw Error('Invalid scene setting.');return {...Object.fromEntries(['category','motion','source','language'].map(k=>[k,raw[k]])),mood:sceneText(raw.mood,300),direction:sceneText(raw.direction,2000),customCategory:sceneText(raw.customCategory,500)};}
export function sceneImage(project,shot,settings=shot.sceneSettings||defaultSceneSettings()){return settings.source==='result'?shot.result:project.reference;}
export function validateSceneDraft(raw){if(!raw||raw.version!==1||typeof raw.applied!=='boolean'||!['vision','template','manual'].includes(raw.origin)||!['reference','result'].includes(raw.source))throw Error('Invalid scene draft.');if(raw.imageKey!==''&&!/^[a-f0-9]{8}:\d{1,8}$/.test(raw.imageKey))throw Error('Invalid scene image key.');return {version:1,applied:raw.applied,origin:raw.origin,source:raw.source,imageKey:raw.imageKey,text:sceneText(raw.text,12000),summary:sceneText(raw.summary,2000),observations:sceneText(raw.observations,2000),base:sceneText(raw.base,30000),model:sceneText(raw.model,180),settings:validateSceneSettings(raw.settings)};}
export function sceneDraftStatus(project,shot,baseVideo,imageKey){const d=shot.sceneDraft;if(!d)return {exists:false,active:false,stale:false};const settings=shot.sceneSettings||defaultSceneSettings(),stale=d.base!==baseVideo||d.imageKey!==imageKey||JSON.stringify(validateSceneSettings(d.settings))!==JSON.stringify(validateSceneSettings(settings));return {exists:true,active:d.applied&&!stale,stale};}
export function templateScene(baseVideo,settings,duration){const intent=SCENE_INTENTS[settings.category]||settings.customCategory||'One simple moment supported by the existing scene.',motion={subtle:'Keep movement minimal and unhurried.',natural:'Use modest, natural movement.',dynamic:'Use one clear energetic movement, preserving stable anatomy and object geometry.'}[settings.motion];return {videoPrompt:[baseVideo,'Scene direction: '+intent,`Develop only one small beat over ${duration} seconds, then let the scene settle.`,motion,settings.mood?'Intended mood: '+settings.mood+'.':'',settings.direction?'Creator direction: '+settings.direction:''].filter(Boolean).join('\n'),summary:'Category-based starting point; check that the suggested action fits the attached image.',observations:''};}
